"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([["243056"],{577453:function(e){e.exports=JSON.parse('{"tag":{"label":"Jetson","permalink":"/tags/jetson","allTagsPath":"/tags","count":8,"items":[{"id":"Edge/NVIDIA_Jetson/Carrier_Boards/J501/Hardware_Interfaces_Usage","title":"Interfaces Usage","description":"Hardware and Interfaces Usage for J501 carrier board","permalink":"/j501_carrier_board_interfaces_usage"},{"id":"Edge/NVIDIA_Jetson/Carrier_Boards/Robotics_J401/Robotics_J401_carrierboard_Hardware_Interfaces_Usage","title":"Interfaces Usage","description":"This wiki provides a comprehensive introduction to the hardware features and interface usage of the reComputer Jetson Robotics J401 carrier board. It covers detailed specifications, supported modules, setup instructions, and practical guides for using various interfaces such as M.2, Ethernet, USB, CAN, UART, I2C, and GMSL2 camera expansion, helping users quickly get started with robotics development on the J401 platform.","permalink":"/recomputer_jetson_robotics_j401_getting_started"},{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Super/reComputer_Super_vs_Classic_Next-Gen_AI_Performance_in_Edge_Inferencing","title":"reComputer Super vs Classic Next-Gen AI Performance in Edge Inferencing","description":"This article highlights the superior AI performance of the reComputer Super compared to the reComputer Classic, demonstrating up to a 1.7x boost in AI compute power with the NVIDIA Jetson Orin NX 16GB. Through practical benchmarks in AI text generation using the DeepSeek-R1:7B model with Ollama, and AI video processing using the YOLOv11 object detection model, the results show that the reComputer Super delivers significantly faster inference speeds and higher GPU frequencies. Notably, it processes approximately 2.37 times more images per second than the Classic. The article also explains the importance of evaluating performance based on terminal-reported FPS rather than on-screen FPS, which can be limited by display and system factors.","permalink":"/recomputer_jetson_super_performance"},{"id":"Spanish/Edge/NVIDIA_Jetson/Carrier_Boards/J501/es_Hardware_Interfaces_Usage","title":"Uso de interfaces","description":"Uso de hardware e interfaces para la Carrier Board J501","permalink":"/es/j501_carrier_board_interfaces_usage"},{"id":"ja/Edge/NVIDIA_Jetson/Carrier_Boards/J501/ja_Hardware_Interfaces_Usage","title":"\u30A4\u30F3\u30BF\u30FC\u30D5\u30A7\u30FC\u30B9\u306E\u4F7F\u7528\u65B9\u6CD5","description":"J501\u30AD\u30E3\u30EA\u30A2\u30DC\u30FC\u30C9\u306E\u30CF\u30FC\u30C9\u30A6\u30A7\u30A2\u304A\u3088\u3073\u30A4\u30F3\u30BF\u30FC\u30D5\u30A7\u30FC\u30B9\u306E\u4F7F\u7528\u65B9\u6CD5","permalink":"/ja/j501_carrier_board_interfaces_usage"},{"id":"ja/Edge/NVIDIA_Jetson/Carrier_Boards/Robotics_J401/ja_Robotics_J401_carrierboard_Hardware_Interfaces_Usage","title":"\u30A4\u30F3\u30BF\u30FC\u30D5\u30A7\u30FC\u30B9\u306E\u4F7F\u7528\u65B9\u6CD5","description":"\u3053\u306E\u30A6\u30A3\u30AD\u3067\u306F\u3001reComputer Jetson Robotics J401\u30AD\u30E3\u30EA\u30A2\u30DC\u30FC\u30C9\u306E\u30CF\u30FC\u30C9\u30A6\u30A7\u30A2\u3068\u30A4\u30F3\u30BF\u30FC\u30D5\u30A7\u30FC\u30B9\u306B\u3064\u3044\u3066\u7D39\u4ECB\u3057\u307E\u3059\u3002","permalink":"/ja/recomputer_jetson_robotics_j401_getting_started"},{"id":"zh-CN/Edge/NVIDIA_Jetson/Carrier_Boards/J501/cn_Hardware_Interfaces_Usage","title":"\u63A5\u53E3\u4F7F\u7528","description":"J501\u8F7D\u677F\u7684\u786C\u4EF6\u548C\u63A5\u53E3\u4F7F\u7528","permalink":"/cn/j501_carrier_board_interfaces_usage"},{"id":"zh-CN/Edge/NVIDIA_Jetson/Carrier_Boards/Robotics_J401/cn_Robotics_J401_carrierboard_Hardware_Interfaces_Usage","title":"\u63A5\u53E3\u4F7F\u7528","description":"\u672C\u6587\u6863\u4ECB\u7ECD\u4E86 reComputer Jetson Robotics J401 \u8F7D\u677F\u7684\u786C\u4EF6\u548C\u63A5\u53E3\u3002","permalink":"/cn/recomputer_jetson_robotics_j401_getting_started"}],"unlisted":false}}')}}]);